"""Structured fuzz: deep trees, many children, bulk blocks, all three forests."""
import json, random, subprocess, sys, os
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from refmodel import ImageValidator, Fail, lpm, mask

RUN = [sys.executable, '/workspace/run.py']


def run(req):
    p = subprocess.run(RUN, input=json.dumps(req).encode(), capture_output=True)
    if p.returncode != 0:
        raise SystemExit("child failed: %s" % p.stderr.decode()[:3000])
    return json.loads(p.stdout.decode())


def make_prefixes(rng):
    out = []
    style = rng.randint(0, 5)
    if style == 0:  # many children under one origin0 parent
        base = rng.getrandbits(128) & ~0xFFFF
        for _ in range(rng.randint(1, 20)):
            out.append((base | (rng.getrandbits(16) << 0), rng.choice([8, 9, 10, 12, 14, 16])))
    elif style == 1:  # origin16 forest, many distinct chunks
        base = (rng.getrandbits(16) << 112)
        for _ in range(rng.randint(1, 20)):
            out.append((base | (rng.getrandbits(48) << 64), rng.choice([17, 18, 22, 23, 30, 40, 64])))
    elif style == 2:  # origin64 forest, deep chains
        base = rng.getrandbits(64) << 64
        for _ in range(rng.randint(1, 15)):
            out.append((base | (rng.getrandbits(64) << 0), rng.choice([65, 70, 76, 100, 120, 127, 128])))
    elif style == 3:  # a chain of increasing lengths
        v = rng.getrandbits(128)
        for l in range(0, 129, rng.choice([1, 5, 6, 13])):
            out.append((v, min(l, 128)))
    elif style == 4:  # mixed all over
        for _ in range(rng.randint(1, 25)):
            out.append((rng.getrandbits(128), rng.choice([0, 1, 6, 12, 16, 17, 22, 28, 64, 65, 70, 76, 122, 128])))
    else:  # dense siblings for bulk children (>= 7 children)
        base = (rng.getrandbits(16) << 112) | (rng.getrandbits(6) << 106)
        for _ in range(rng.randint(7, 20)):
            out.append((base | (rng.getrandbits(6) << 100), 22 + rng.choice([0, 1, 2, 3, 4, 5])))
    return out


def main():
    seed = int(sys.argv[1]) if len(sys.argv) > 1 else 1
    rounds = int(sys.argv[2]) if len(sys.argv) > 2 else 20
    rng = random.Random(seed)
    for it in range(rounds):
        prefixes = make_prefixes(rng)
        ops = []
        fib = {}
        saved = []
        loaded = None
        nops = rng.randint(5, 60)
        for _ in range(nops):
            r = rng.random()
            if r < 0.45:
                value, length = rng.choice(prefixes)
                hop = rng.randint(0, 4194302)
                ops.append(["put", "%032x" % value, length, hop])
                fib[(length, mask(value, length))] = hop
            elif r < 0.6:
                value, length = rng.choice(prefixes)
                ops.append(["query", ["%032x" % value]])
            elif r < 0.72:
                ops.append(["query", ["%032x" % rng.getrandbits(128) for _ in range(3)]) if False else ["%032x" % rng.getrandbits(128)])
            elif r < 0.82 and len(saved) < 3:
                ops.append(["save"])
                saved.append(dict(fib))
            elif r < 0.92 and saved:
                ops.append(["load_saved", rng.randrange(len(saved))])
            else:
                ops.append(["image_query", ["%032x" % rng.getrandbits(128)]])
        req = {"cases": [{"ops": ops}]}
        resp = run(req)
        if "error" in resp:
            raise SystemExit("error response: %s" % json.dumps(req)[:500])
        res = resp["results"][0]
        for img in res["snapshots"]:
            try:
                v = ImageValidator(img)
                v.run()
            except Fail as e:
                raise SystemExit("invalid image (seed %d it %d): %s\n%s" % (seed, it, e, json.dumps(img)[:4000]))
        # replay
        fib = {}
        saved = []
        loaded = None
        expected = []
        exp_loads = []
        for op in ops:
            if op[0] == "put":
                value = int(op[1], 16)
                fib[(op[2], mask(value, op[2]))] = op[3]
            elif op[0] == "query":
                for a in op[1]:
                    expected.append(lpm(fib, int(a, 16)))
            elif op[0] == "save":
                saved.append(dict(fib))
            elif op[0] == "load_saved":
                exp_loads.append(True)
                loaded = saved[op[1]]
            elif op[0] == "image_query":
                cur = loaded if loaded is not None else {}
                for a in op[1]:
                    expected.append(lpm(cur, int(a, 16)))
        if res["answers"] != expected:
            raise SystemExit("answers mismatch seed %d it %d\nops=%s\ngot =%s\nwant=%s" % (seed, it, json.dumps(ops), res["answers"], expected))
        if res["loads"] != exp_loads:
            raise SystemExit("loads mismatch seed %d: %s vs %s" % (seed, res["loads"], exp_loads))
        for img, snap in zip(res["snapshots"], saved):
            v = ImageValidator(img)
            prefixes_out = v.run()
            if prefixes_out != snap:
                raise SystemExit("fib mismatch seed %d\n got=%s\nwant=%s" % (seed, sorted(prefixes_out.items()), sorted(snap.items())))
    print("fuzz2 ok seed=%d rounds=%d" % (seed, rounds))


main()
